// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// @file: Approved normal and invalid-input scenarios.
// @spec: COR
// @consumers: fixture consumer
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { boundedDelay } from './delay.ts';

test('[COR-REQ-1] public behavior', () => {
  // contract: the smaller finite nonnegative argument wins, with zero as a valid result
  assert.strictEqual(boundedDelay(200, 50), 50);
  assert.strictEqual(boundedDelay(50, 200), 50);
  assert.strictEqual(boundedDelay(100, 100), 100);
  assert.strictEqual(boundedDelay(0, 50), 0);
  assert.strictEqual(boundedDelay(50, 0), 0);
  assert.strictEqual(boundedDelay(0, 0), 0);
});

test('[COR-REQ-2] invalid input', () => {
  // failure mode: every rejected argument throws RangeError; message text is not part of the contract
  assert.throws(() => boundedDelay(-1, 50), RangeError);
  assert.throws(() => boundedDelay(200, -1), RangeError);
  assert.throws(() => boundedDelay(Number.NaN, 50), RangeError);
  assert.throws(() => boundedDelay(200, Number.NaN), RangeError);
  assert.throws(() => boundedDelay(Number.POSITIVE_INFINITY, 50), RangeError);
  assert.throws(() => boundedDelay(200, Number.NEGATIVE_INFINITY), RangeError);
  assert.throws(() => boundedDelay('200' as unknown as number, 50), RangeError);
  assert.throws(() => boundedDelay(200, '50' as unknown as number), RangeError);
  assert.throws(() => boundedDelay(-1, -1), RangeError);
});

// @file: Deterministic delay bound selection.
// @spec: COR
// @consumers: fixture consumer

/**
 * @purpose Select the smaller of a requested delay and its allowed limit.
 * @param value Requested delay in milliseconds.
 * @param limit Maximum permitted delay in milliseconds.
 * @throws {RangeError} When either argument is not a finite nonnegative number; value is checked before limit.
 * @returns The smaller delay in milliseconds.
 */
export function boundedDelay(value: number, limit: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new RangeError(`[boundedDelay] value must be a finite nonnegative number, received ${String(value)}`);
  }
  if (typeof limit !== 'number' || !Number.isFinite(limit) || limit < 0) {
    throw new RangeError(`[boundedDelay] limit must be a finite nonnegative number, received ${String(limit)}`);
  }
  return Math.min(value, limit);
}
